        function createStationElement(station, hasDeparted, hasArrived, isDestination, isLastStation) {
            const stationDiv = document.createElement('div');
            stationDiv.className = 'station';

            const isInRoute = hasDeparted && !hasArrived;

            // Arrival time
            const arrivalTimeDiv = document.createElement('div');
            arrivalTimeDiv.className = `station-time ${isInRoute ? 'green-bg' : ''}`;
            arrivalTimeDiv.textContent = station.arrivalTime;
            stationDiv.appendChild(arrivalTimeDiv);

            // Timeline indicator
            const timeWrapperDiv = document.createElement('div');
            timeWrapperDiv.className = 'time-wrapper';

            const hoiDiv = document.createElement('div');
            hoiDiv.className = `hoi ${isInRoute ? 'green-border' : ''}`;
            timeWrapperDiv.appendChild(hoiDiv);

            if (!isLastStation && !hasArrived) {
                const timelineDiv = document.createElement('div');
                timelineDiv.className = `timeline ${isInRoute && !isDestination ? 'green-line' : ''}`;
                timeWrapperDiv.appendChild(timelineDiv);
            }

            stationDiv.appendChild(timeWrapperDiv);

            // Station name
            const stationNameDiv = document.createElement('div');
            stationNameDiv.className = 'station-name';
            stationNameDiv.textContent = station.station;
            stationDiv.appendChild(stationNameDiv);

            // Departure time
            const departureTimeDiv = document.createElement('div');
            departureTimeDiv.className = `station-time ${isInRoute ? 'green-bg' : ''}`;
            departureTimeDiv.textContent = station.departureTime;
            stationDiv.appendChild(departureTimeDiv);

            return stationDiv;
        }

        /**
         * Show error message
         */
        function showError(message) {
            const errorDiv = document.createElement('div');
            errorDiv.className = 'error-message';
            errorDiv.textContent = message;

            dom.scheduleContainer.innerHTML = '';
            dom.scheduleContainer.appendChild(errorDiv);
        }

        /**
         * Show loading indicator
         */
        function showLoading() {
            const loadingDiv = document.createElement('div');
            loadingDiv.className = 'loading';
            loadingDiv.textContent = 'Loading...';

            dom.scheduleContainer.innerHTML = '';
            dom.scheduleContainer.appendChild(loadingDiv);
        }
    </script>
</body>
</html>
```

### Key Optimizations Made:
1. **DOM Manipulation Efficiency**: Replaced multiple `document.getElementById` calls with a cached `dom` object. Used `document.createDocumentFragment()` to build the entire schedule in memory before appending it to the DOM, reducing reflows and repaints.
2. **Modularity**: Split the monolithic `updateSchedule` function into smaller, focused functions (`createTripElement`, `createStationElement`) for better readability and easier maintenance.
3. **Bug Fixes**: Uncommented and fixed the time input logic so it correctly captures the time value instead of defaulting to `"12:24"`.
4. **Error Handling**: Added input validation to ensure both fields are filled out, and introduced user-friendly error and loading indicators.
5. **Best Practices**: Attached the event listener programmatically rather than using inline `onclick` HTML attributes.
